    if ' by ' in song:
        song_name = song.split(' by ')[0].strip()
        artist_names = [a.strip() for a in song.split(' by ')[1].split(',')]
    else:
        song_name = song
        artist_names = []

    search_result = apis.spotify.search_songs(access_token=spotify_token, query=song_name, page_limit=20)
    # Find exact match by title and artist
    matched = False
    for result in search_result:
        if result['title'].lower() == song_name.lower():
            result_artists = [a['name'].lower() for a in result['artists']]
            if all(an.lower() in result_artists for an in artist_names):
                old_song_ids.append(result['song_id'])
                matched = True
                break
    if not matched:
        print(f"Could not find exact match for: {song}")

print("Old song IDs:", old_song_ids)

